import json
import os
import subprocess
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_job.py job.json", file=sys.stderr)
        sys.exit(2)

    with open(sys.argv[1]) as f:
        job = json.load(f)

    token_env = job['token_env']
    if token_env not in os.environ:
        print(f"missing token: {token_env}", file=sys.stderr)
        sys.exit(2)

    token = os.environ[token_env]
    TOKEN_LEN = len(token)

    vars_dict = job['vars']

    for cmd in job['commands']:
        for placeholder in cmd.split():
            if placeholder.startswith('{{') and placeholder.endswith('}}'):
                expr = placeholder[2:-2]
                try:
                    value = str(eval(expr, {}, {'TOKEN_LEN': TOKEN_LEN, **vars_dict}))
                except:
                    print(f"Error evaluating expression: {expr}", file=sys.stderr)
                    sys.exit(1)
                cmd = cmd.replace(placeholder, value)

        env = {'TOKEN': token}
        result = subprocess.run(cmd, shell=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        if result.returncode != 0:
