import json
import os
import subprocess
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_job.py job.json", file=sys.stderr)
        sys.exit(2)

    with open(sys.argv[1], 'r') as f:
        job_data = json.load(f)

    token_env = job_data.get('token_env')
    if not token_env:
        print("missing token: token_env not provided in job.json", file=sys.stderr)
        sys.exit(2)

    token = os.getenv(token_env)
    if not token:
        print(f"missing token: {token_env}", file=sys.stderr)
        sys.exit(2)

    vars_dict = job_data.get('vars', {})
    commands = job_data.get('commands', [])

    for cmd in commands:
        for expr in cmd.split('{{'):
            if expr.endswith('}}'):
                expr_name = expr[:-2]
                if expr_name in vars_dict:
                    cmd = cmd.replace(f'{{{{{expr_name}}}}}', str(vars_dict[expr_name]))
                else:
                    print(f"Error: variable '{expr_name}' not found in vars", file=sys.stderr)
                    sys.exit(1)

        env = os.environ.copy()
        env['TOKEN'] = token

        try:
            result = subprocess.run(cmd, shell=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
            if result.returncode != 0:
                print(result.stderr, file=sys.stderr)
                sys.exit(1)
            print(result.stdout, end='')
        except Exception as e:
            print(f"Error executing command: {e}", file=sys.stderr)
            sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import json
import os
import subprocess
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_job.py job.json", file=sys.stderr)
        sys.exit(2)

    with open(sys.argv[1], 'r') as f:
        job = json.load(f)

    token_env = job['token_env']
    if not os.getenv(token_env):
        print(f"missing token: {token_env}", file=sys.stderr)
        sys.exit(2)

    token = os.getenv(token_env)
    vars_dict = job['vars']

    def replace_expr(expr):
        tokens = expr.split()
        result = tokens[0]
        for token in tokens[1:]:
            if token == '+':
                a, b = result.split()
                result = str(int(vars_dict[a]) + int(vars_dict[b]))
            else:
                result = str(vars_dict[token])
        return result

    def replace_placeholders(cmd):
        return cmd.replace('{{', '').replace('}}', '').replace('{{', '').split(';')
    commands = []
    for part in replace_placeholders(job['command']):
        parts = part.split()
        if parts:
            for i, token in enumerate(parts):
                if token.startswith('{{') and token.endswith('}}'):
                    expr = token[2:-2]
                    parts[i] = replace_expr(expr)
            commands.append(' '.join(parts))

    cmd_str = '; '.join(commands)
    env = os.environ.copy()
    env['TOKEN'] = token

    result = subprocess.run(cmd_str, shell=True, text=True, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    sys.stdout.write(result.stdout)
    sys.stderr.write(result.stderr)
    sys.exit(result.returncode)

if __name__ == "__main__":
    main()
